def _solid_jpeg(width: int, height: int, rgb: tuple[int, int, int]) -> bytes:
    try:
        from PIL import Image
    except ImportError:
        raise RuntimeError("Pillow required to synthesize new colors; use embedded filenames instead.")
    img = Image.new("RGB", (width, height), rgb)
    buf = io.BytesIO()
    img.save(buf, format="JPEG", quality=85)
    return buf.getvalue()


def generate() -> None:
    """Write the three spike fixture JPEGs."""
    for filename in _EMBEDDED_JPEGS:
        path = FIXTURE_DIR / filename
        path.write_bytes(base64.b64decode(_EMBEDDED_JPEGS[filename]))
        print(f"Wrote {path.name} ({path.stat().st_size} bytes)")


if __name__ == "__main__":
    generate()
